// =========================================================================
// MODUL PRESENSI & ABSENSI PEGAWAI - FRONTEND CONTROLLER (AbsensiJS.html)
// =========================================================================

window.AbsensiState = {
  currentDate: '',       // Format YYYY-MM-DD
  formattedDate: '',     // Format DD-MM-YYYY
  currentDayName: '',    // Senin, Selasa, dst.
  currentDayIndex: 1,    // 0=Minggu, 1=Senin, ..., 6=Sabtu
  currentShift: 'Pagi',  // 'Pagi' atau 'Sore'
  activeWorkers: [],     // Hanya pekerja yang berstatus Aktif
  presensiHariIni: [],   // Presensi tersimpan di tanggal ini
  kalenderLibur: [],     // Daftar hari libur
  shiftAttendance: { pagi: {}, sore: {} }, // Cache input form terpisah per shift (Pagi & Sore)
  attendanceMap: {},     // { [namaPekerja]: { status: 'Hadir'|'Tidak', keterangan: '' } } untuk shift aktif
  isMinggu: false,
  isLibur: false,
  infoLibur: null,
  spreadsheetUrl: ''
};

function syncAbsensiRoleVisibility() {
  let role = String(window.activeUserRole || '').trim().toLowerCase();
  let isOwner = (role === 'owner' || role === 'super user');

  let btnLibur = document.getElementById('btnAturLiburAbsensi');
  let btnSheet = document.getElementById('btnBukaSheetAbsensi');
  let btnBannerLibur = document.getElementById('btnUbahJadwalLiburBanner');
  let btnTab3Libur = document.getElementById('btnTambahLiburTab3');

  if (btnLibur) {
    if (isOwner) {
      btnLibur.classList.remove('hidden');
      btnLibur.classList.add('flex');
    } else {
      btnLibur.classList.add('hidden');
      btnLibur.classList.remove('flex');
    }
  }
  if (btnSheet) {
    if (isOwner) {
      btnSheet.classList.remove('hidden');
      btnSheet.classList.add('flex');
    } else {
      btnSheet.classList.add('hidden');
      btnSheet.classList.remove('flex');
    }
  }
  if (btnBannerLibur) {
    if (isOwner) btnBannerLibur.classList.remove('hidden'); else btnBannerLibur.classList.add('hidden');
  }
  if (btnTab3Libur) {
    if (isOwner) {
      btnTab3Libur.classList.remove('hidden');
      btnTab3Libur.classList.add('flex');
    } else {
      btnTab3Libur.classList.add('hidden');
      btnTab3Libur.classList.remove('flex');
    }
  }
}
window.syncAbsensiRoleVisibility = syncAbsensiRoleVisibility;

/**
 * Inisialisasi Modul Absensi saat pertama kali dibuka dari menu.
 */
function initAbsensiModule() {
  syncAbsensiRoleVisibility();
  if (!window.AbsensiState.currentDate) {
    let now = new Date();
    let y = now.getFullYear();
    let m = String(now.getMonth() + 1).padStart(2, '0');
    let d = String(now.getDate()).padStart(2, '0');
    window.AbsensiState.currentDate = y + '-' + m + '-' + d;
  }
  let datePicker = document.getElementById('absensiDatePicker');
  if (datePicker) {
    datePicker.value = window.AbsensiState.currentDate;
  }
  loadAbsensiData(window.AbsensiState.currentDate);
}

/**
 * Beralih tab tampilan absensi (harian, rekap, libur).
 */
function switchTabAbsensi(tabKey) {
  ['harian', 'rekap', 'libur'].forEach(k => {
    let content = document.getElementById('tabContentAbsensi' + k.charAt(0).toUpperCase() + k.slice(1));
    let btn = document.getElementById('tabBtnAbsensi' + k.charAt(0).toUpperCase() + k.slice(1));
    if (content) {
      if (k === tabKey) {
        content.classList.remove('hidden');
      } else {
        content.classList.add('hidden');
      }
    }
    if (btn) {
      if (k === tabKey) {
        btn.className = "tab-btn-absensi px-4 py-2 rounded-xl text-xs font-bold transition-all bg-indigo-600 text-white shadow-md shadow-indigo-600/30 flex items-center gap-2";
      } else {
        btn.className = "tab-btn-absensi px-4 py-2 rounded-xl text-xs font-bold transition-all bg-slate-800/60 text-slate-300 hover:text-white hover:bg-slate-800 flex items-center gap-2";
      }
    }
  });

  if (tabKey === 'rekap') {
    renderRekapBulanan();
  } else if (tabKey === 'libur') {
    renderKalenderLibur();
  }
}

/**
 * Navigasi tanggal mundur/maju delta hari.
 */
function navigasiHariAbsensi(deltaDays) {
  let cur = new Date(window.AbsensiState.currentDate || new Date());
  cur.setDate(cur.getDate() + deltaDays);
  let y = cur.getFullYear();
  let m = String(cur.getMonth() + 1).padStart(2, '0');
  let d = String(cur.getDate()).padStart(2, '0');
  let newDateStr = y + '-' + m + '-' + d;
  handleAbsensiDateChange(newDateStr);
}

function setTanggalAbsensiHariIni() {
  let now = new Date();
  let y = now.getFullYear();
  let m = String(now.getMonth() + 1).padStart(2, '0');
  let d = String(now.getDate()).padStart(2, '0');
  let todayStr = y + '-' + m + '-' + d;
  handleAbsensiDateChange(todayStr);
}

function handleAbsensiDateChange(newDateStr) {
  if (!newDateStr) return;
  window.AbsensiState.currentDate = newDateStr;
  let datePicker = document.getElementById('absensiDatePicker');
  if (datePicker) datePicker.value = newDateStr;
  loadAbsensiData(newDateStr);
}

/**
 * Memilih shift Pagi atau Sore dan memperbarui tombol & jadwal jam kerja.
 */
function pilihShiftAbsensi(shiftName) {
  let oldShiftKey = (window.AbsensiState.currentShift || 'Pagi').toLowerCase();
  if (!window.AbsensiState.shiftAttendance) {
    window.AbsensiState.shiftAttendance = { pagi: {}, sore: {} };
  }
  // Simpan state shift yang baru saja aktif
  window.AbsensiState.shiftAttendance[oldShiftKey] = Object.assign({}, window.AbsensiState.attendanceMap);

  window.AbsensiState.currentShift = shiftName;
  let newShiftKey = shiftName.toLowerCase();
  if (!window.AbsensiState.shiftAttendance[newShiftKey]) {
    window.AbsensiState.shiftAttendance[newShiftKey] = {};
  }
  // Hubungkan attendanceMap ke shift yang baru dipilih
  window.AbsensiState.attendanceMap = window.AbsensiState.shiftAttendance[newShiftKey];

  updateShiftSelectorUI();
  renderAbsensiTable();
}

/**
 * Mengupdate tampilan UI selector Shift (Jam shift Senin-Jumat vs Sabtu).
 */
function updateShiftSelectorUI() {
  let dayIdx = window.AbsensiState.currentDayIndex; // 6 = Sabtu
  let btnPagi = document.getElementById('btnShiftPagi');
  let btnSore = document.getElementById('btnShiftSore');
  let badgePagi = document.getElementById('badgeJamShiftPagi');
  let badgeSore = document.getElementById('badgeJamShiftSore');

  // Aturan Jadwal:
  // Senin - Jumat : Pagi (10.00 - 15.00), Sore (16.00 - 20.00)
  // Sabtu         : Pagi (10.00 - 14.00), Sore (14.00 - 18.00)
  let jamPagi = (dayIdx === 6) ? "10.00 - 14.00" : "10.00 - 15.00";
  let jamSore = (dayIdx === 6) ? "14.00 - 18.00" : "16.00 - 20.00";

  if (badgePagi) badgePagi.innerText = jamPagi;
  if (badgeSore) badgeSore.innerText = jamSore;

  let isPagi = (window.AbsensiState.currentShift === 'Pagi');
  if (btnPagi) {
    if (isPagi) {
      btnPagi.className = "px-5 py-2.5 rounded-xl text-sm font-extrabold transition-all bg-amber-500 text-white border border-amber-600 shadow-md flex items-center gap-2.5 hover:scale-[1.02]";
    } else {
      btnPagi.className = "px-5 py-2.5 rounded-xl text-sm font-extrabold transition-all text-slate-600 hover:text-slate-900 hover:bg-slate-200/60 flex items-center gap-2.5";
    }
  }

  if (btnSore) {
    if (!isPagi) {
      btnSore.className = "px-5 py-2.5 rounded-xl text-sm font-extrabold transition-all bg-indigo-600 text-white border border-indigo-700 shadow-md flex items-center gap-2.5 hover:scale-[1.02]";
    } else {
      btnSore.className = "px-5 py-2.5 rounded-xl text-sm font-extrabold transition-all text-slate-600 hover:text-slate-900 hover:bg-slate-200/60 flex items-center gap-2.5";
    }
  }
}

/**
 * Menghitung jadwal jam kerja saat ini.
 */
function getJadwalShiftCurrent() {
  let dayIdx = window.AbsensiState.currentDayIndex;
  let isPagi = (window.AbsensiState.currentShift === 'Pagi');
  if (dayIdx === 6) { // Sabtu
    return isPagi ? { jamMulai: "10:00", jamSelesai: "14:00", label: "10.00 - 14.00" } 
                  : { jamMulai: "14:00", jamSelesai: "18:00", label: "14.00 - 18.00" };
  } else { // Senin - Jumat
    return isPagi ? { jamMulai: "10:00", jamSelesai: "15:00", label: "10.00 - 15.00" } 
                  : { jamMulai: "16:00", jamSelesai: "20:00", label: "16.00 - 20.00" };
  }
}

/**
 * Memuat data absensi dari Google Apps Script Backend (getAbsensiModuleData).
 */
function loadAbsensiData(dateStr) {
  let tbody = document.getElementById('tbodyAbsensiPegawai');
  if (tbody) {
    tbody.innerHTML = `
      <tr>
        <td colspan="7" class="px-4 py-12 text-center text-slate-400">
          <div class="inline-block animate-spin text-xl mb-2">⏳</div>
          <p>Memuat daftar pegawai aktif & presensi shift...</p>
        </td>
      </tr>
    `;
  }

  let formattedQueryDate = dateStr;
  if (dateStr && dateStr.indexOf('-') !== -1 && dateStr.split('-')[0].length === 4) {
    let p = dateStr.split('-');
    formattedQueryDate = p[2] + '-' + p[1] + '-' + p[0];
  }

  if (typeof google !== 'undefined' && google.script && google.script.run) {
    google.script.run
      .withSuccessHandler(function(res) {
        if (!res || !res.success) {
          showToast('error', res && res.message ? res.message : 'Gagal memuat data absensi.');
          return;
        }
        applyAbsensiDataToState(res);
      })
      .withFailureHandler(function(err) {
        showToast('error', 'Koneksi backend gagal: ' + err.message);
      })
      .getAbsensiModuleData(formattedQueryDate);
  } else {
    // Mode Standalone / Test Harness Fallback
    fallbackLoadAbsensiLocal(formattedQueryDate);
  }
}

function refreshAbsensiData() {
  loadAbsensiData(window.AbsensiState.currentDate);
}

/**
 * Menyimpan data respon backend ke state dan merender UI.
 */
function applyAbsensiDataToState(res) {
  window.AbsensiState.formattedDate = res.date || '';
  window.AbsensiState.currentDayName = res.dayName || '';
  window.AbsensiState.isMinggu = Boolean(res.isMinggu);
  window.AbsensiState.isLibur = Boolean(res.isLibur);
  window.AbsensiState.infoLibur = res.infoLibur || null;
  window.AbsensiState.kalenderLibur = res.kalenderLibur || [];
  window.AbsensiState.rekapBulanan = res.rekapBulanan || [];
  window.AbsensiState.presensiHariIni = res.presensiHariIni || [];
  window.AbsensiState.spreadsheetUrl = res.spreadsheetUrl || '';

  // Hitung dayIndex dari date YYYY-MM-DD atau DD-MM-YYYY
  if (window.AbsensiState.currentDate) {
    let p = window.AbsensiState.currentDate.split('-');
    let d = (p[0].length === 4)
      ? new Date(parseInt(p[0], 10), parseInt(p[1], 10) - 1, parseInt(p[2], 10))
      : new Date(parseInt(p[2], 10), parseInt(p[1], 10) - 1, parseInt(p[0], 10));
    window.AbsensiState.currentDayIndex = d.getDay();
  }

  // Filter pekerja aktif: jika status pekerja "Tidak Aktif", mereka TIDAK MUNCUL di absen!
  let rawWorkers = res.activeWorkers || [];
  window.AbsensiState.activeWorkers = rawWorkers.map(w => {
    let cleanNama = (w.namaPekerja || w.nama || w.namaLengkap || w.namaPegawai || w.nama_pekerja || '').trim();
    return Object.assign({}, w, { namaPekerja: cleanNama });
  }).filter(w => {
    if (!w.namaPekerja) return false;
    let st = String(w.status || "Aktif").trim().toLowerCase();
    return st !== "tidak aktif" && st !== "non aktif" && st !== "nonaktif" && st !== "inactive";
  });

  // Tampilkan label tanggal & hari
  let lbl = document.getElementById('labelHariTanggal');
  if (lbl) {
    lbl.innerText = window.AbsensiState.currentDayName + ', ' + window.AbsensiState.formattedDate;
  }

  // Tampilkan status banner libur operasional
  updateOperasionalBannerUI();

  // Reset cache input form per shift saat data tanggal dimuat
  window.AbsensiState.shiftAttendance = { pagi: {}, sore: {} };
  let curShiftKey = (window.AbsensiState.currentShift || 'Pagi').toLowerCase();
  window.AbsensiState.attendanceMap = window.AbsensiState.shiftAttendance[curShiftKey];

  // Update jadwal shift sesuai hari
  updateShiftSelectorUI();

  // Render tabel presensi
  renderAbsensiTable();
}

/**
 * Mengecek apakah presensi pada tanggal saat ini dikunci.
 * Kondisi kunci:
 * 1. Hari Minggu (isMinggu === true)
 * 2. Hari Libur Nasional / Khusus dengan status operasional Tutup (statusOperasional === 'Tutup')
 */
function isAbsensiLockedToday() {
  if (window.AbsensiState.isMinggu) return true;
  if (window.AbsensiState.infoLibur) {
    let opStatus = String(window.AbsensiState.infoLibur.statusOperasional || 'Tutup').trim().toLowerCase();
    return opStatus === 'tutup';
  }
  if (window.AbsensiState.isLibur) return true;
  return false;
}

/**
 * Menampilkan status banner operasional (Minggu / Libur Nasional / Buka Normal).
 */
function updateOperasionalBannerUI() {
  let badgeOperasional = document.getElementById('badgeStatusOperasional');
  let banner = document.getElementById('bannerStatusLibur');
  let bannerIcon = document.getElementById('bannerIconLibur');
  let bannerJudul = document.getElementById('bannerJudulLibur');
  let bannerKet = document.getElementById('bannerKeteranganLibur');

  let isMinggu = window.AbsensiState.isMinggu;
  let infoLibur = window.AbsensiState.infoLibur;

  if (isMinggu) {
    if (badgeOperasional) {
      badgeOperasional.className = "px-2.5 py-0.5 rounded-full text-xs font-bold bg-rose-100 text-rose-800 border border-rose-300";
      badgeOperasional.innerHTML = "🛑 Tutup (Libur Minggu)";
    }
    if (banner) {
      banner.className = "mt-4 p-4 rounded-xl border bg-rose-50 border-rose-200 transition-all block";
      if (bannerIcon) bannerIcon.innerText = "🛑";
      if (bannerJudul) {
        bannerJudul.className = "text-sm font-bold text-rose-900";
        bannerJudul.innerText = "Hari Minggu: Klinik Libur Rutin";
      }
      if (bannerKet) {
        bannerKet.className = "text-xs text-rose-700 mt-0.5";
        bannerKet.innerText = "Sesuai jadwal klinik, hari Minggu libur operasional. Pengisian presensi dikunci (default Tidak Hadir).";
      }
    }
  } else if (infoLibur) {
    let opStatus = infoLibur.statusOperasional || "Tutup";
    let isTutup = (opStatus === "Tutup");
    if (badgeOperasional) {
      badgeOperasional.className = isTutup 
        ? "px-2.5 py-0.5 rounded-full text-xs font-bold bg-amber-100 text-amber-800 border border-amber-300"
        : "px-2.5 py-0.5 rounded-full text-xs font-bold bg-sky-100 text-sky-800 border border-sky-300";
      badgeOperasional.innerHTML = (isTutup ? "🏖️ " : "⚡ ") + opStatus + " (" + infoLibur.kategoriLibur + ")";
    }
    if (banner) {
      banner.className = isTutup
        ? "mt-4 p-4 rounded-xl border bg-amber-50 border-amber-200 transition-all block"
        : "mt-4 p-4 rounded-xl border bg-sky-50 border-sky-200 transition-all block";
      if (bannerIcon) bannerIcon.innerText = isTutup ? "🏖️" : "🏥";
      if (bannerJudul) {
        bannerJudul.className = isTutup ? "text-sm font-bold text-amber-900" : "text-sm font-bold text-sky-900";
        bannerJudul.innerText = infoLibur.namaHariLibur + " (" + opStatus + ")";
      }
      if (bannerKet) {
        bannerKet.className = isTutup ? "text-xs text-amber-700 mt-0.5" : "text-xs text-sky-700 mt-0.5";
        bannerKet.innerText = isTutup 
          ? ((infoLibur.keterangan ? infoLibur.keterangan + " — " : "") + "Klinik libur operasional (" + opStatus + "). Pengisian presensi shift dikunci.")
          : (infoLibur.keterangan || ("Kategori: " + infoLibur.kategoriLibur + " - Status operasional klinik: " + opStatus));
      }
    }
  } else {
    if (badgeOperasional) {
      badgeOperasional.className = "px-2.5 py-0.5 rounded-full text-xs font-bold bg-emerald-100 text-emerald-800 border border-emerald-300";
      badgeOperasional.innerHTML = "🟢 Buka Normal";
    }
    if (banner) {
      banner.className = "mt-4 p-4 rounded-xl border hidden";
    }
  }
}

/**
 * Render tabel presensi pegawai untuk shift terpilih.
 * Status_Absensi strictly: 'Hadir' atau 'Tidak'.
 * Default: 'Tidak' (Tidak Hadir).
 */
function renderAbsensiTable() {
  let tbody = document.getElementById('tbodyAbsensiPegawai');
  if (!tbody) return;

  let workers = window.AbsensiState.activeWorkers || [];
  let curShift = window.AbsensiState.currentShift || 'Pagi';
  let curShiftKey = curShift.toLowerCase();
  let jadwal = getJadwalShiftCurrent();
  let presensiSaved = window.AbsensiState.presensiHariIni || [];
  let isLocked = isAbsensiLockedToday();

  // Tombol Simpan Presensi Shift: Kunci jika hari libur operasional / Minggu
  let btnSimpan = document.getElementById('btnSimpanAbsensi');
  if (btnSimpan) {
    if (isLocked) {
      btnSimpan.disabled = true;
      btnSimpan.className = "px-7 py-3 bg-slate-200 text-slate-500 rounded-xl text-sm font-bold border border-slate-300 cursor-not-allowed flex items-center gap-2.5 shadow-none";
      btnSimpan.innerHTML = '<span>🔒</span> Presensi Dikunci (Hari Libur)';
      btnSimpan.title = 'Presensi tidak dapat diisi pada hari Minggu / Libur Operasional';
    } else {
      btnSimpan.disabled = false;
      btnSimpan.className = "px-7 py-3 bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 text-white rounded-xl text-sm font-black shadow-lg shadow-emerald-600/30 transition-all flex items-center gap-2.5 hover:scale-[1.03] active:scale-[0.98]";
      btnSimpan.innerHTML = '<span>💾</span> Simpan Presensi Shift';
      btnSimpan.removeAttribute('title');
    }
  }

  let autoInd = document.getElementById('autosaveIndicator');
  if (autoInd) {
    autoInd.innerHTML = isLocked ? '<span class="text-rose-600 font-bold">🔒 Form Presensi Terkunci</span>' : '';
  }

  if (!window.AbsensiState.shiftAttendance) {
    window.AbsensiState.shiftAttendance = { pagi: {}, sore: {} };
  }
  if (!window.AbsensiState.shiftAttendance[curShiftKey]) {
    window.AbsensiState.shiftAttendance[curShiftKey] = {};
  }
  window.AbsensiState.attendanceMap = window.AbsensiState.shiftAttendance[curShiftKey];

  if (workers.length === 0) {
    tbody.innerHTML = `
      <tr>
        <td colspan="5" class="px-4 py-8 text-center text-slate-500">
          <p class="font-bold text-amber-700">Tidak ada pegawai aktif ditemukan di Sheet Pengaturan_Tarif_Shift.</p>
          <p class="text-[11px] text-slate-500 mt-1">Pastikan nama pekerja telah terdaftar dan berstatus 'Aktif' di Master User & Role.</p>
        </td>
      </tr>
    `;
    updateAbsensiStats();
    return;
  }

  // Map riwayat presensi yang sudah tersimpan untuk shift ini
  let shiftRecords = presensiSaved.filter(p => (p.shift || '').toLowerCase() === curShift.toLowerCase());
  let savedStatusMap = {};
  shiftRecords.forEach(r => {
    let nm = (r.namaPekerja || '').trim().toLowerCase();
    if (nm) {
      savedStatusMap[nm] = {
        status: r.statusAbsensi || 'Tidak',
        keterangan: r.keterangan || ''
      };
    }
  });

  // Tampilkan status penyimpanan shift ini
  let statSimpan = document.getElementById('statStatusTersimpan');
  let statWaktu = document.getElementById('statWaktuSimpan');
  if (isLocked) {
    if (statSimpan) statSimpan.innerHTML = '<span class="text-rose-700 font-extrabold">🔒 Libur Operasional</span>';
    if (statWaktu) statWaktu.innerText = 'Klinik Tutup (Presensi Dikunci)';
  } else if (shiftRecords.length > 0) {
    if (statSimpan) statSimpan.innerHTML = '<span class="text-emerald-700 font-extrabold">✅ Sudah Disimpan</span>';
    if (statWaktu) statWaktu.innerText = 'Tersimpan ' + shiftRecords.length + ' pegawai';
  } else {
    if (statSimpan) statSimpan.innerHTML = '<span class="text-amber-700 font-extrabold">⏳ Belum Disimpan</span>';
    if (statWaktu) statWaktu.innerText = 'Draft belum ke sheet';
  }

  let htmlRows = '';
  workers.forEach((w, idx) => {
    let namaClean = (w.namaPekerja || w.nama || w.namaLengkap || w.namaPegawai || w.nama_pekerja || '').trim();
    let namaKey = namaClean.toLowerCase();
    
    // Inisialisasi map input
    // User request: Default status absensi adalah Tidak hadir.
    // Jika hari libur / tutup, status strictly 'Tidak'
    if (isLocked) {
      window.AbsensiState.attendanceMap[namaKey] = {
        status: 'Tidak',
        keterangan: 'Libur Operasional'
      };
    } else if (!window.AbsensiState.attendanceMap[namaKey]) {
      if (savedStatusMap[namaKey]) {
        window.AbsensiState.attendanceMap[namaKey] = {
          status: savedStatusMap[namaKey].status,
          keterangan: savedStatusMap[namaKey].keterangan || ''
        };
      } else {
        // Default strictly 'Tidak' (Tidak Hadir)
        window.AbsensiState.attendanceMap[namaKey] = {
          status: 'Tidak',
          keterangan: ''
        };
      }
    }

    let curAtt = window.AbsensiState.attendanceMap[namaKey];
    let isHadir = (curAtt.status === 'Hadir');

    // Role badge color (high contrast light theme)
    let rBadge = "bg-slate-100 text-slate-700 border-slate-200";
    let roleLower = (w.role || "").toLowerCase();
    if (roleLower.includes("dokter")) {
      rBadge = "bg-indigo-50 text-indigo-700 border-indigo-200";
    } else if (roleLower.includes("perawat")) {
      rBadge = "bg-emerald-50 text-emerald-700 border-emerald-200";
    } else if (roleLower.includes("admin") || roleLower.includes("kasir") || roleLower.includes("office")) {
      rBadge = "bg-amber-50 text-amber-800 border-amber-200";
    } else if (roleLower.includes("owner")) {
      rBadge = "bg-purple-50 text-purple-700 border-purple-200";
    }

    htmlRows += `
      <tr class="transition-colors ${isHadir ? 'hover:bg-emerald-50/50' : 'hover:bg-slate-50'}">
        <td class="px-4 py-3.5 text-center text-slate-600 font-bold">${idx + 1}</td>
        
        <td class="px-4 py-3.5">
          <div class="font-bold text-slate-900 text-sm tracking-tight">${escapeHtml(namaClean)}</div>
        </td>

        <td class="px-4 py-3.5">
          <span class="inline-flex items-center px-2.5 py-1 rounded-full text-xs font-bold border ${rBadge}">
            ${escapeHtml(w.role || 'Staf')}
          </span>
        </td>

        <td class="px-4 py-3.5 font-bold text-slate-700">
          <div class="flex items-center gap-1.5">
            <span class="text-sm">${curShift === 'Pagi' ? '☀️' : '🌙'}</span>
            <span class="text-xs font-semibold text-slate-800">${jadwal.label}</span>
          </div>
        </td>

        <td class="px-4 py-3.5">
          <!-- Status_Absensi strictly: (Hadir / Tidak) -->
          <div class="relative">
            ${isLocked ? `
              <select disabled 
                      class="w-full px-3 py-2 rounded-xl font-bold text-xs border bg-slate-100 text-slate-500 border-slate-300 cursor-not-allowed opacity-80"
                      title="Presensi dikunci pada hari libur / klinik tutup">
                <option value="Tidak" selected>🔒 Libur (Tidak Hadir)</option>
              </select>
            ` : `
              <select onchange="updateWorkerAbsensi('${escapeHtml(namaClean)}', this.value)" 
                      class="w-full px-3 py-2 rounded-xl font-black text-xs border focus:ring-2 focus:outline-none transition-all cursor-pointer ${
                        isHadir 
                          ? 'bg-emerald-50 text-emerald-800 border-emerald-400 focus:ring-emerald-500' 
                          : 'bg-rose-50 text-rose-800 border-rose-300 focus:ring-rose-500'
                      }">
                <option value="Tidak" ${!isHadir ? 'selected' : ''}>🔴 Tidak Hadir</option>
                <option value="Hadir" ${isHadir ? 'selected' : ''}>🟢 Hadir</option>
              </select>
            `}
          </div>
        </td>
      </tr>
    `;
  });

  tbody.innerHTML = htmlRows;
  updateAbsensiStats();
}

/**
 * Update nilai status absensi pekerja individual.
 */
function updateWorkerAbsensi(namaPekerja, val) {
  if (isAbsensiLockedToday()) {
    showToast('warning', 'Presensi dikunci pada Hari Libur / Klinik Tutup.');
    return;
  }
  let key = (namaPekerja || '').trim().toLowerCase();
  if (!window.AbsensiState.attendanceMap[key]) {
    window.AbsensiState.attendanceMap[key] = { status: 'Tidak', keterangan: '' };
  }
  window.AbsensiState.attendanceMap[key].status = (val === 'Hadir' ? 'Hadir' : 'Tidak');
  renderAbsensiTable();
}

/**
 * Toggle cepat Hadir / Tidak untuk pekerja.
 */
function toggleWorkerAbsensi(namaPekerja) {
  if (isAbsensiLockedToday()) {
    showToast('warning', 'Presensi dikunci pada Hari Libur / Klinik Tutup.');
    return;
  }
  let key = (namaPekerja || '').toLowerCase();
  let cur = window.AbsensiState.attendanceMap[key] ? window.AbsensiState.attendanceMap[key].status : 'Tidak';
  updateWorkerAbsensi(namaPekerja, cur === 'Hadir' ? 'Tidak' : 'Hadir');
}

/**
 * Update catatan keterangan pekerja.
 */
function updateWorkerKeterangan(namaPekerja, ket) {
  if (isAbsensiLockedToday()) return;
  let key = (namaPekerja || '').toLowerCase();
  if (!window.AbsensiState.attendanceMap[key]) {
    window.AbsensiState.attendanceMap[key] = { status: 'Hadir', keterangan: '' };
  }
  window.AbsensiState.attendanceMap[key].keterangan = String(ket || '').trim();
}

/**
 * Aksi Cepat: Tandai Semua Hadir.
 */
function quickMarkAllHadir() {
  if (isAbsensiLockedToday()) {
    showToast('warning', 'Presensi dikunci pada Hari Libur / Klinik Tutup.');
    return;
  }
  (window.AbsensiState.activeWorkers || []).forEach(w => {
    let key = (w.namaPekerja || '').toLowerCase();
    if (!window.AbsensiState.attendanceMap[key]) {
      window.AbsensiState.attendanceMap[key] = { status: 'Hadir', keterangan: '' };
    }
    window.AbsensiState.attendanceMap[key].status = 'Hadir';
    if (window.AbsensiState.attendanceMap[key].keterangan === 'Libur Operasional') {
      window.AbsensiState.attendanceMap[key].keterangan = '';
    }
  });
  renderAbsensiTable();
  showToast('info', 'Semua pegawai aktif ditandai Hadir pada Shift ' + window.AbsensiState.currentShift);
}

/**
 * Aksi Cepat: Tandai Semua Tidak Hadir.
 */
function quickMarkAllTidak() {
  if (isAbsensiLockedToday()) {
    showToast('warning', 'Presensi dikunci pada Hari Libur / Klinik Tutup.');
    return;
  }
  (window.AbsensiState.activeWorkers || []).forEach(w => {
    let key = (w.namaPekerja || '').toLowerCase();
    if (!window.AbsensiState.attendanceMap[key]) {
      window.AbsensiState.attendanceMap[key] = { status: 'Tidak', keterangan: '' };
    }
    window.AbsensiState.attendanceMap[key].status = 'Tidak';
  });
  renderAbsensiTable();
  showToast('info', 'Semua status pegawai direset ke Tidak Hadir');
}

/**
 * Update badge statistik ringkasan di atas tabel.
 */
function updateAbsensiStats() {
  let workers = window.AbsensiState.activeWorkers || [];
  let hadirCount = 0;
  let tidakCount = 0;

  workers.forEach(w => {
    let key = (w.namaPekerja || '').toLowerCase();
    let att = window.AbsensiState.attendanceMap[key];
    if (att && att.status === 'Hadir') {
      hadirCount++;
    } else {
      tidakCount++;
    }
  });

  let elTotal = document.getElementById('statTotalPegawai');
  let elHadir = document.getElementById('statTotalHadir');
  let elTidak = document.getElementById('statTotalTidakHadir');

  if (elTotal) elTotal.innerText = workers.length;
  if (elHadir) elHadir.innerText = hadirCount;
  if (elTidak) elTidak.innerText = tidakCount;
}

/**
 * Menyimpan data Presensi Shift ke Spreadsheet 12 Presensi & Absensi Pegawai.
 */
function simpanAbsensiShiftCurrent() {
  if (isAbsensiLockedToday()) {
    showToast('warning', 'Presensi tidak dapat disimpan karena klinik libur operasional / tutup.');
    return;
  }
  let workers = window.AbsensiState.activeWorkers || [];
  if (workers.length === 0) {
    showToast('warning', 'Tidak ada data pegawai aktif untuk disimpan.');
    return;
  }

  let jadwal = getJadwalShiftCurrent();
  let shiftName = window.AbsensiState.currentShift;
  let records = [];

  workers.forEach(w => {
    let key = (w.namaPekerja || '').toLowerCase();
    let att = window.AbsensiState.attendanceMap[key] || { status: 'Tidak', keterangan: '' };
    records.push({
      idPekerja: w.idAturan || ('STF-' + w.namaPekerja.substring(0, 3).toUpperCase()),
      namaPekerja: w.namaPekerja,
      role: w.role || 'Staff',
      statusAbsensi: att.status === 'Hadir' ? 'Hadir' : 'Tidak',
      keterangan: att.keterangan || ''
    });
  });

  let payload = {
    tanggal: window.AbsensiState.formattedDate,
    hari: window.AbsensiState.currentDayName,
    shift: shiftName,
    jamMulai: jadwal.jamMulai,
    jamSelesai: jadwal.jamSelesai,
    records: records,
    verifikator: window.activeNamaAccount || "Admin"
  };

  let btnSimpan = document.getElementById('btnSimpanAbsensi');
  if (btnSimpan) {
    btnSimpan.disabled = true;
    btnSimpan.innerHTML = '<span>⏳</span> Menyimpan...';
  }

  if (typeof google !== 'undefined' && google.script && google.script.run) {
    google.script.run
      .withSuccessHandler(function(res) {
        if (btnSimpan) {
          btnSimpan.disabled = false;
          btnSimpan.innerHTML = '<span>💾</span> Simpan Presensi Shift';
        }
        if (!res || !res.success) {
          showToast('error', res && res.message ? res.message : 'Gagal menyimpan absensi.');
          return;
        }
        showToast('success', res.message || 'Presensi shift berhasil disimpan!');
        loadAbsensiData(window.AbsensiState.currentDate);
      })
      .withFailureHandler(function(err) {
        if (btnSimpan) {
          btnSimpan.disabled = false;
          btnSimpan.innerHTML = '<span>💾</span> Simpan Presensi Shift';
        }
        showToast('error', 'Gagal menghubungi server: ' + err.message);
      })
      .simpanAbsensiShift(payload);
  } else {
    // Mode Standalone / Test Harness
    setTimeout(function() {
      if (btnSimpan) {
        btnSimpan.disabled = false;
        btnSimpan.innerHTML = '<span>💾</span> Simpan Presensi Shift';
      }
      showToast('success', 'Presensi Shift ' + shiftName + ' berhasil disimpan (Mode Lokal)!');
      // Update data presensiHariIni di state
      records.forEach(r => {
        let existing = window.AbsensiState.presensiHariIni.find(x => 
          (x.namaPekerja || '').toLowerCase() === r.namaPekerja.toLowerCase() && 
          (x.shift || '').toLowerCase() === shiftName.toLowerCase()
        );
        if (existing) {
          existing.statusAbsensi = r.statusAbsensi;
          existing.keterangan = r.keterangan;
        } else {
          window.AbsensiState.presensiHariIni.push({
            idPresensi: 'ATT-' + Date.now(),
            tanggal: window.AbsensiState.formattedDate,
            hari: window.AbsensiState.currentDayName,
            shift: shiftName,
            jamMulai: jadwal.jamMulai,
            jamSelesai: jadwal.jamSelesai,
            idPekerja: r.idPekerja,
            namaPekerja: r.namaPekerja,
            role: r.role,
            statusAbsensi: r.statusAbsensi,
            keterangan: r.keterangan,
            verifikator: 'Admin'
          });
        }
      });

      // Sinkronkan ke modul Payroll jika window.PayrollState aktif
      if (window.PayrollState && Array.isArray(window.PayrollState.presensiHarian)) {
        let sNorm = (shiftName.toLowerCase().indexOf('sore') !== -1 || shiftName.indexOf('2') !== -1) ? 'Shift 2' : 'Shift 1';
        records.forEach(r => {
          let nama = String(r.namaPekerja || '').trim();
          let isHadir = String(r.statusAbsensi || '').toLowerCase() === 'hadir';
          let uangHarian = 0;
          if (isHadir) {
            let foundT = (window.PayrollState.tarifShift || []).find(t => String(t.namaPekerja || '').toLowerCase() === nama.toLowerCase());
            if (foundT) {
              uangHarian = (sNorm === 'Shift 2') ? (Number(foundT.tarifShift2) || 0) : (Number(foundT.tarifShift1) || 0);
            } else {
              uangHarian = (r.role || '').toLowerCase().indexOf('dokter') !== -1 ? 55000 : 45000;
            }
          }

          let exPay = window.PayrollState.presensiHarian.find(x => 
            (x.namaPekerja || '').toLowerCase() === nama.toLowerCase() &&
            (x.tanggal || '') === window.AbsensiState.formattedDate &&
            (x.shift || '').toLowerCase() === sNorm.toLowerCase()
          );

          if (exPay) {
            exPay.statusKehadiran = r.statusAbsensi;
            exPay.uangHarianDidapat = uangHarian;
            exPay.jamMasuk = jadwal.jamMulai;
            exPay.jamPulang = jadwal.jamSelesai;
          } else {
            window.PayrollState.presensiHarian.unshift({
              idPresensi: 'ATT-' + Date.now().toString().slice(-6),
              tanggal: window.AbsensiState.formattedDate,
              idPekerja: r.idPekerja || 'STF-001',
              namaPekerja: nama,
              role: r.role || 'Staff',
              shift: sNorm,
              jamMasuk: jadwal.jamMulai,
              jamPulang: jadwal.jamSelesai,
              statusKehadiran: r.statusAbsensi,
              uangHarianDidapat: uangHarian,
              verifikator: 'Admin'
            });
          }
        });
        if (typeof renderAllPayrollTables === 'function') {
          renderAllPayrollTables();
        }
      }

      renderAbsensiTable();
    }, 100);
  }
}

/**
 * Menghitung jumlah Hari Kerja dalam suatu bulan:
 * Hari Kerja = (Jumlah hari dalam bulan tersebut) - (Jumlah hari libur).
 * Hari libur meliputi:
 * - Setiap hari Minggu rutin pada bulan tersebut
 * - Setiap tanggal libur nasional / cuti / khusus klinik yang berstatus "Tutup"
 *   (tidak dihitung dobel jika hari libur bertepatan dengan hari Minggu).
 */
function hitungHariKerjaBulan(periodeBulan, kalenderLibur) {
  let now = new Date();
  let monthIdx = now.getMonth();
  let year = now.getFullYear();

  const bulanMap = {
    "januari": 0, "februari": 1, "maret": 2, "april": 3, "mei": 4, "juni": 5,
    "juli": 6, "agustus": 7, "september": 8, "oktober": 9, "november": 10, "desember": 11
  };

  if (periodeBulan) {
    let p = String(periodeBulan).trim().toLowerCase().split(/\s+/);
    if (p.length >= 2) {
      if (bulanMap[p[0]] !== undefined) monthIdx = bulanMap[p[0]];
      let y = parseInt(p[1], 10);
      if (!isNaN(y)) year = y;
    }
  }

  // Jumlah hari dalam bulan
  let totalDays = new Date(year, monthIdx + 1, 0).getDate();
  let holidaySet = {};

  // 1. Hari Minggu
  for (let day = 1; day <= totalDays; day++) {
    let d = new Date(year, monthIdx, day);
    if (d.getDay() === 0) {
      let key = String(day).padStart(2, '0') + '-' + String(monthIdx + 1).padStart(2, '0') + '-' + year;
      holidaySet[key] = true;
    }
  }

  // 2. Hari Libur yang status Operasionalnya Tutup
  let kList = kalenderLibur || (window.AbsensiState && window.AbsensiState.kalenderLibur) || [];
  if (Array.isArray(kList)) {
    kList.forEach(h => {
      let st = String(h.statusOperasional || "Tutup").trim().toLowerCase();
      if (st === "tutup") {
        let tgl = String(h.tanggal || "").trim();
        if (tgl.indexOf('-') !== -1) {
          let sp = tgl.split('-');
          let dObj = (sp[0].length === 4)
            ? new Date(parseInt(sp[0], 10), parseInt(sp[1], 10) - 1, parseInt(sp[2], 10))
            : new Date(parseInt(sp[2], 10), parseInt(sp[1], 10) - 1, parseInt(sp[0], 10));

          if (dObj.getMonth() === monthIdx && dObj.getFullYear() === year) {
            let key = String(dObj.getDate()).padStart(2, '0') + '-' + String(monthIdx + 1).padStart(2, '0') + '-' + year;
            holidaySet[key] = true;
          }
        }
      }
    });
  }

  let totalLibur = Object.keys(holidaySet).length;
  let hariKerja = Math.max(0, totalDays - totalLibur);
  return {
    totalDays: totalDays,
    totalLibur: totalLibur,
    hariKerja: hariKerja
  };
}

/**
 * Render Tabel Rekap Kehadiran Bulanan.
 */
function renderRekapBulanan() {
  let tbody = document.getElementById('tbodyRekapBulanan');
  if (!tbody) return;

  let rekap = window.AbsensiState.rekapBulanan || [];
  let workers = window.AbsensiState.activeWorkers || [];
  let curBulan = document.getElementById('selectBulanRekap') ? document.getElementById('selectBulanRekap').value : "Oktober 2026";
  let infoHK = hitungHariKerjaBulan(curBulan, window.AbsensiState.kalenderLibur);

  let badgeHK = document.getElementById('badgeHariKerjaRekap');
  if (badgeHK) {
    badgeHK.innerText = "📅 Hari Kerja: " + infoHK.hariKerja + " Hari (Total " + infoHK.totalDays + " - Libur " + infoHK.totalLibur + ")";
  }

  if (rekap.length === 0 && workers.length === 0) {
    tbody.innerHTML = `
      <tr>
        <td colspan="10" class="px-4 py-8 text-center text-slate-400">Belum ada data rekap kehadiran bulanan.</td>
      </tr>
    `;
    return;
  }

  // Gabungkan dengan pekerja aktif
  let html = '';
  workers.forEach((w, idx) => {
    let found = rekap.find(r => (r.namaPekerja || '').toLowerCase() === (w.namaPekerja || '').toLowerCase());
    let pagi = found ? found.totalShiftPagi : 0;
    let sore = found ? found.totalShiftSore : 0;
    let hadir = found ? found.totalHadir : (pagi + sore);
    let tidak = found ? found.totalTidakHadir : 0;
    let hk = (found && found.hariKerja) ? found.hariKerja : infoHK.hariKerja;
    let pct = found ? found.persentase : (hadir > 0 ? '100.0%' : '0%');

    html += `
      <tr class="transition-colors hover:bg-slate-50">
        <td class="px-4 py-3.5 text-center text-slate-600 font-bold">${idx + 1}</td>
        <td class="px-4 py-3.5 font-bold text-slate-900">${escapeHtml(w.namaPekerja)}</td>
        <td class="px-4 py-3.5 text-slate-600">${escapeHtml(w.role || 'Staf')}</td>
        <td class="px-4 py-3.5 text-center font-extrabold text-indigo-700">${hk} Hari</td>
        <td class="px-4 py-3.5 text-center font-bold text-amber-700">${pagi}</td>
        <td class="px-4 py-3.5 text-center font-bold text-indigo-700">${sore}</td>
        <td class="px-4 py-3.5 text-center font-black text-emerald-700">${hadir}</td>
        <td class="px-4 py-3.5 text-center font-black text-rose-700">${tidak}</td>
        <td class="px-4 py-3.5 text-center font-black text-cyan-800">${pct}</td>
        <td class="px-4 py-3.5 text-center">
          <button onclick="lihatDetailPresensiPegawai('${escapeHtml(w.namaPekerja)}')" class="px-2.5 py-1 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-xs font-semibold border border-slate-300 transition-all">
            Detail
          </button>
        </td>
      </tr>
    `;
  });

  tbody.innerHTML = html;
}

