/**
 * Fallback data lokal jika dijalankan di mode web standalone / test harness.
 */
function fallbackLoadAbsensiLocal(queryDate) {
  let parts = queryDate.split('-');
  let dObj = (parts[0].length === 4) 
    ? new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10))
    : new Date(parseInt(parts[2], 10), parseInt(parts[1], 10) - 1, parseInt(parts[0], 10));

  const dayNames = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
  let dIdx = dObj.getDay();
  let dayName = dayNames[dIdx];
  let isSun = (dIdx === 0);

  // Ambil daftar pekerja dari PayrollState.tarifShift atau KlinikData.staff
  let workers = [];
  if (window.PayrollState && window.PayrollState.tarifShift && window.PayrollState.tarifShift.length > 0) {
    workers = window.PayrollState.tarifShift;
  } else if (window.KlinikData && window.KlinikData.staff) {
    workers = window.KlinikData.staff.map((s, i) => ({
      idAturan: s.idPekerja || s.id || ("SN-" + String(i + 1).padStart(2, '0')),
      idPekerja: s.idPekerja || s.id || ("SN-" + String(i + 1).padStart(2, '0')),
      namaPekerja: s.nama,
      role: s.role,
      status: s.status || "Aktif",
      tarifShift1: 45000,
      tarifShift2: 45000
    }));
  } else {
    workers = [
      { idAturan: "SN-01", idPekerja: "SN-01", namaPekerja: "Vembrian Asung Nugroho", role: "Owner", status: "Aktif" },
      { idAturan: "SN-02", idPekerja: "SN-02", namaPekerja: "drg. Rahma Yulinda D, Sp. BMM", role: "Dokter Gigi Spesialis", status: "Aktif" },
      { idAturan: "SN-03", idPekerja: "SN-03", namaPekerja: "drg. Regyana Oktavaria", role: "Dokter Gigi Umum", status: "Aktif" },
      { idAturan: "SN-04", idPekerja: "SN-04", namaPekerja: "drg. Tia Ardhana R", role: "Dokter Gigi Umum", status: "Aktif" },
      { idAturan: "SN-06", idPekerja: "SN-06", namaPekerja: "Eva Nurmiza, AMKG", role: "Perawat Gigi", status: "Aktif" },
      { idAturan: "SN-07", idPekerja: "SN-07", namaPekerja: "Fitriyati, AMKG", role: "Perawat Gigi", status: "Aktif" },
      { idAturan: "SN-08", idPekerja: "SN-08", namaPekerja: "Riri Afriyanti", role: "Perawat Umum", status: "Aktif" },
      { idAturan: "SN-09", idPekerja: "SN-09", namaPekerja: "Sri Purwanti", role: "Admin", status: "Aktif" }
    ];
  }

  // Filter HANYA pekerja Aktif dan pastikan namaPekerja valid
  let activeW = workers.map(w => {
    let cleanNama = (w.namaPekerja || w.nama || w.namaLengkap || w.namaPegawai || w.nama_pekerja || '').trim();
    return Object.assign({}, w, { namaPekerja: cleanNama });
  }).filter(w => {
    if (!w.namaPekerja) return false;
    let st = String(w.status || "Aktif").trim().toLowerCase();
    return st !== "tidak aktif" && st !== "non aktif" && st !== "nonaktif" && st !== "inactive";
  });

  let mockRes = {
    success: true,
    date: queryDate,
    dayName: dayName,
    isMinggu: isSun,
    isLibur: isSun,
    infoLibur: isSun ? {
      tanggal: queryDate,
      hari: "Minggu",
      kategoriLibur: "Libur Rutin Minggu",
      namaHariLibur: "Libur Rutin Akhir Pekan (Minggu)",
      statusOperasional: "Tutup",
      keterangan: "Klinik Libur Rutin Hari Minggu"
    } : null,
    activeWorkers: activeW,
    presensiHariIni: window.AbsensiState.presensiHariIni || [],
    kalenderLibur: [
      { tanggal: "01-01-2026", hari: "Kamis", namaHariLibur: "Tahun Baru 2026", kategoriLibur: "Libur Nasional", statusOperasional: "Tutup", keterangan: "Libur Nasional" },
      { tanggal: "17-08-2026", hari: "Senin", namaHariLibur: "Hari Kemerdekaan RI", kategoriLibur: "Libur Nasional", statusOperasional: "Tutup", keterangan: "Libur Nasional" }
    ],
    rekapBulanan: []
  };

  applyAbsensiDataToState(mockRes);
}

function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}



